style.css:
/* Applies to the entire page */
body {
    background: radial-gradient(circle, rgba(0, 0, 0, 0.8), #000000), 
                url('https://your-image-host.com/starry-image.png') no-repeat center center fixed;
    background-size: cover;
    color: white; /* Ensures text remains readable */
}

/* Optional: Customize specific elements */
div, header, footer {
    background: transparent !important; /* Makes sections transparent if needed */
}
